    const runs = noCases ? [] : [['completed', 100, '18', '2', 0.91], ['failed', 41, '5', '8', 0.52], ['completed', 100, '19', '1', 0.95]].concat(sc === 'running' ? [['running', 58, '9', '1', 0.0]] : []).map((x, i) => ({ id: 'run' + i, st: x[0], p: x[1], pass: +x[2], fail: +x[3], score: x[4] }));
