    const mets = [['事实正确性', 0.4, many ? 0.52 : 0.91, '82/11'], ['引用完整性', 0.3, many ? 0.4 : 0.88, '79/14'], ['回答完整度', 0.2, low ? null : 0.86, low ? '—' : '80/13'], ['延迟', 0.1, low ? null : 0.95, low ? '—' : '93/0'], ['安全合规', 0, low ? null : 1, low ? '—' : '100/0']];
